window.STORY_CHAPTERS["c6f21ef30d1856fe6"]={"id":"c6f21ef30d1856fe6","lines":[{"uid":"talk.lottery_1#originalText","id":"talk.lottery_1","speaker":{},"text":{"cn":"让您久等了。","en":"Sorry to keep you waiting.","ja":"お待たせ致しました"},"kind":"narration"},{"uid":"talk.lottery_2#originalText","id":"talk.lottery_2","speaker":{},"text":{"cn":"请问您要到第几层呢？","en":"Which floor would you like to go to?","ja":"何階をご利用でしょうか"},"kind":"narration"},{"uid":"talk.lottery_3#originalText","id":"talk.lottery_3","speaker":{},"text":{"cn":"好的。","en":"Yes, sir.","ja":"かしこまりました"},"kind":"narration"},{"uid":"talk.lottery_4#originalText","id":"talk.lottery_4","speaker":{},"text":{"cn":"System call。Generate aerial element。","en":"System Call Generate Aerial Element","ja":"システムコールジェネレート・エアリアルエレメント"},"kind":"narration"},{"uid":"talk.lottery_5#originalText","id":"talk.lottery_5","speaker":{},"text":{"cn":"我想用这台升降盘，","en":"I would love to fly freely","ja":"あの空を、この昇降盤で"},"kind":"narration"},{"uid":"talk.lottery_6#originalText","id":"talk.lottery_6","speaker":{},"text":{"cn":"自由地在天空飞翔……","en":"on this lift...","ja":"自由に飛んでみたい・・・"},"kind":"narration"},{"uid":"talk.lottery_7#originalText","id":"talk.lottery_7","speaker":{},"text":{"cn":"Burst element。","en":"Burst Element","ja":"バーストエレメント"},"kind":"narration"},{"uid":"talk.lottery_pc_130114001#originalText","id":"talk.lottery_pc_130114001","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我想守护这个世界的人们！！","en":"I want to protect the people of this world!","ja":"この世界の人たちを、守りたい!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114002#originalText","id":"talk.lottery_pc_130114002","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"不知道从什么时候开始，像这样两人一起好像已经变了理所当然的事啊。","en":"I don't when it happened, but it feels natural that we're together like this.","ja":"いつの間にか、こうしてふたりでいるのが当たり前になってたよ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114003#originalText","id":"talk.lottery_pc_130114003","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我一定会取回亚丝娜的记忆！！我不能输！！","en":"I will bring back Asuna's memories! I can’t lose!","ja":"アスナの記憶は、俺が必ず取り戻す!!負けるわけにはいかないんだ!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114004#originalText","id":"talk.lottery_pc_130114004","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"真的是⋯⋯太简单了！","en":"I can't believe it... this is too tepid!","ja":"まったく…ヌルすぎるぜ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114005#originalText","id":"talk.lottery_pc_130114005","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我一定会，超越给你们看！！","en":"I'll show you what I'm made of!","ja":"必ず、乗り越えてみせる!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114006#originalText","id":"talk.lottery_pc_130114006","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"要连续攻击了！","en":"Let's combo-attack 'em!","ja":"連続で叩き込むぞ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114007#originalText","id":"talk.lottery_pc_130114007","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"只要我认真做，还是能做到的。","en":"Whatever I do, I can do it.","ja":"僕だって、やればできるんだ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114009#originalText","id":"talk.lottery_pc_130114009","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我只要记得那个人就好。","en":"For me, I only need to know that person.","ja":"僕はあの人だけを知っていればいい"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114010#originalText","id":"talk.lottery_pc_130114010","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"难得的安息日，跟我出去真的好吗？","en":"Are you really okay going out with me on your vacation?","ja":"せっかくの安息日なのに僕と外出でいいのかい?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114011#originalText","id":"talk.lottery_pc_130114011","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嗯……我会站起来。为了你，不论几次我都会站起来。","en":"If it's for you, I'll stand up... However many times that may be.","ja":"ああ……立つよお前のためなら、何度だって"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114012#originalText","id":"talk.lottery_pc_130114012","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……蓝蔷薇之剑， 助我一臂之力吧！","en":"Lend me your strength! Blue Rose Sword!","ja":"僕に力を貸してくれ、青薔薇の剣!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114013#originalText","id":"talk.lottery_pc_130114013","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"来，我们走吧。","en":"Shall we get going?","ja":"さぁ、行こうか"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114014#originalText","id":"talk.lottery_pc_130114014","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我要……往前进。","en":"I must...press on.","ja":"僕は……前に進むんだ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114015#originalText","id":"talk.lottery_pc_130114015","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"喔……是套奇特的服装呢。这适合我吗？","en":"What an odd outfit... Do you think it suits me?","ja":"へぇ……不思議な衣装だね似合うかな?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114016#originalText","id":"talk.lottery_pc_130114016","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"今天过得非常开心呢！因、因为可以见到你……","en":"I-I had so much fun today! M-Mostly because you were here with me...","ja":"今日がすごく楽しみだったんだき、君に会えるから……"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114017#originalText","id":"talk.lottery_pc_130114017","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"不给糖……我就要把你吃掉啰～！……骗你的啦嘻嘻～","en":"If I don't get any treats...  I'll eat you right up!  Hehe, how does that sound?","ja":"お菓子をくれないと……食べちゃうぞぉ〜! ……なんてね"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114019#originalText","id":"talk.lottery_pc_130114019","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"没错，我就是封弊者。","en":"That's right... I am a beater.","ja":"そうだ、俺はビーターだ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114020#originalText","id":"talk.lottery_pc_130114020","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"不管几次……我都会重新振作起来的！","en":"We will never... give up!","ja":"何度でも……立ち上がってみせる!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114021#originalText","id":"talk.lottery_pc_130114021","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"虽然这衣服不方便活动，但我不会认输的哦！","en":"It's a little hard to move around in this, but that won't stop me!","ja":"動きづらい服だけど、負けないよ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114022#originalText","id":"talk.lottery_pc_130114022","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"走吧，为了这个世界──应该还有我们能做到的事才对。","en":"Let's get going. There's still much to do for this world.","ja":"行こう。この世界のために出来ることが、まだあるはずだ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130114023#originalText","id":"talk.lottery_pc_130114023","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"很好！保持这步调继续吧。","ja":"よし、この調子で行こう"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124001#originalText","id":"talk.lottery_pc_130124001","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"做好觉悟了吗？我会使出全力的。","en":"Are you ready? Here I come!","ja":"覚悟はいいですか?全力で参ります"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124002#originalText","id":"talk.lottery_pc_130124002","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"你能跟上我的速度吗。","en":"Think you can match my speed?","ja":"あたしのスピ—ドに追いつけるかな"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124004#originalText","id":"talk.lottery_pc_130124004","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"跟你相遇之后，我觉得自己变强了。","en":"I feel like I have gotten stronger just by meeting you.","ja":"お前と出会ったことで私は強くなれた気がする"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124005#originalText","id":"talk.lottery_pc_130124005","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"别小看集成骑士。","en":"Don't mess with the Integrity Knights","ja":"整合騎士をなめないでね"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124006#originalText","id":"talk.lottery_pc_130124006","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天的风真舒服啊。","en":"The wind today feels nice","ja":"今日の風は気持ちがいいですね"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124007#originalText","id":"talk.lottery_pc_130124007","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"怎么这副表情啦？来想一下开心的事吧！","en":"Why the long face? Come on, think positively!","ja":"なに難しい顔してるの? もっと楽しいこと考えましょう!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124008#originalText","id":"talk.lottery_pc_130124008","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天难得天气这么好，我想让这把剑再多晒一点太阳。","en":"Since the weather is good today, let's get this sword plenty of sunshine.","ja":"今日はいい日和ですからこの剣にたっぷりと陽の光を浴びせてあげましょう"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124009#originalText","id":"talk.lottery_pc_130124009","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"辛苦了。呐，我们来回想一下过去，要不要跟我比试一下？","en":"Good work today. Hey, wanna relive the good old days and have a little duel? ","ja":"お疲れさまねえ、昔を思い出してちょっと試合してみない? "},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124010#originalText","id":"talk.lottery_pc_130124010","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"要试一下味道吗？","en":"Wanna have a taste?","ja":"ちょっと味見、してみるか?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124011#originalText","id":"talk.lottery_pc_130124011","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"心情激动起来了！","en":"Things are heating up!","ja":"テンション上がってきた!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124012#originalText","id":"talk.lottery_pc_130124012","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"能在你的身边，已经是我意想不到的幸福。","en":"Just having it on the side is an unexpected blessing.","ja":"傍に置いていただけるだけで望外の幸福です"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124013#originalText","id":"talk.lottery_pc_130124013","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"我是为了不让你通过这里而来的。","en":"I'm here so that you can't pass through.","ja":"私は、あなたを通さないためにここにいます"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124015#originalText","id":"talk.lottery_pc_130124015","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我一定会守护我们的世界。","en":"We will protect our world, no matter what.","ja":"私たちの世界は、必ず守ります"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124016#originalText","id":"talk.lottery_pc_130124016","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我要用这力量……！","en":"With this power...!","ja":"この力で……!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124017#originalText","id":"talk.lottery_pc_130124017","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"你……现在，稍微变软了。","en":"You...Softened up, just now.","ja":"あなた……今、ちょっと柔らかくなった"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124018#originalText","id":"talk.lottery_pc_130124018","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"我不会输给哥哥的！","en":"I won't lose against you, Kirito!","ja":"お兄ちゃんには負けないよ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124019#originalText","id":"talk.lottery_pc_130124019","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"叫我了？什么事？","en":"You called? What is it?","ja":"呼んだ? 何か用?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124020#originalText","id":"talk.lottery_pc_130124020","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"呵呵，不知道能不能看完这么多呢。","en":"Hehe. I get to read so much!","ja":"ふふ、こんなに読めるかしら"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124021#originalText","id":"talk.lottery_pc_130124021","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"哇……！好漂亮的森林。","en":"Wooow! What a beautiful forest!","ja":"わぁ……! 綺麗な森だなぁ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124022#originalText","id":"talk.lottery_pc_130124022","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"这件泳装会不会太性感了……不过偶尔也还好吧？呵呵。","en":"I wonder if this swimsuit was a little too bold... Hehe. It should be fine, once in awhile.","ja":"ちょっとこの水着大胆だったかな……たまにはいいよね、ふふ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124023#originalText","id":"talk.lottery_pc_130124023","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"泳衣原来也挺方便活动的。","en":"Moving around in a swimsuit is easier than I thought!","ja":"水着って案外動きやすいわね"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124024#originalText","id":"talk.lottery_pc_130124024","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我是人界的骑士爱丽丝！！","en":"I am Alice, a Knight of the Human Empire!","ja":"我、人界の騎士アリス!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124026#originalText","id":"talk.lottery_pc_130124026","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"偶尔就放松一下嘛。","en":"Let's relax and take it easy from time to time!","ja":"たまにはゆっくりしようよ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124027#originalText","id":"talk.lottery_pc_130124027","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"我想要找到和你相遇的意义……","en":"I want to find the meaning of our encounter...","ja":"君と出会った意味を見つけたいんだ……"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124028#originalText","id":"talk.lottery_pc_130124028","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"请、请你不要那样盯着我看，太令人害臊了啦……","en":"D-Don't look at me like that! Aren't you embarrassed of yourself...?","ja":"そ、そんなに見ないでください恥ずかしいではありませんか……"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124029#originalText","id":"talk.lottery_pc_130124029","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"来吧，爱丽丝！去洗澡！洗澡～！","en":"Alice! Let's go take a bath! It's bath time!","ja":"さ、アリス!お風呂行こう!お風呂〜!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124031#originalText","id":"talk.lottery_pc_130124031","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"不管是怎样的对手我也会打倒他！","en":"I'll cut down whoever stands in my way!","ja":"どんな相手だって切り伏せてみせるわ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124032#originalText","id":"talk.lottery_pc_130124032","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"Discharge！","en":"Discharge!","ja":"ディスチャ—ジ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124033#originalText","id":"talk.lottery_pc_130124033","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"接下这把灌注了我所有意念的剑吧……！！","en":"All my power rests within this sword. Just try and block it!","ja":"すべてを込めたあたしの剣……受けてみなさい!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124034#originalText","id":"talk.lottery_pc_130124034","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"有破绽！","en":"There's an opening!","ja":"隙ありっ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124035#originalText","id":"talk.lottery_pc_130124035","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"金木樨真的很适合你。因为金木樨的花就很香呀。","en":"Osmanthus is perfect for you. Those flowers are so sweet and fragrant.","ja":"金木犀ってあなたにピッタリだって、すごくいい匂いがするものあの花"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124036#originalText","id":"talk.lottery_pc_130124036","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"这棵树的上面是我很喜欢的地方喔。","en":"By the way, the top of this tree is my favorite spot.","ja":"あのね、この木の上はあたしのお気に入りの場所なんだ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124037#originalText","id":"talk.lottery_pc_130124037","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我是第一次穿这种衣服……总感觉得静不下心。","en":"This is my first time wearing such an outfit ...I can't stop shaking.","ja":"このような服を着るのは初めてで……なんだか落ち着きません"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124038#originalText","id":"talk.lottery_pc_130124038","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"呼……出了一身汗后，果然会想洗澡清爽一下呀～","en":"Whoo... Worked up quiet a sweat! A bath would be good right about now.","ja":"ふぅ……一汗流した後はやっぱりお風呂に入りたくなるな〜"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124039#originalText","id":"talk.lottery_pc_130124039","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"就算和故乡的天空并不相同，也一定是连系在一起的……是这样没错吧……","en":"I may be far from home, but when I look up at the sky, I realize I'm closer than I thought.","ja":"故郷の空とは違ってもきっと繋がっている……そうよね"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124040#originalText","id":"talk.lottery_pc_130124040","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"你有看到吗？哥哥！","en":"Are you looking at me big brother?","ja":"見ててくれた? お兄ちゃん!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124041#originalText","id":"talk.lottery_pc_130124041","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"我听说有宝藏！要不要一起去调查看看！","en":"Word on the street is there's treasure! Let's look for it together!","ja":"お宝があるって噂を聞いたの!一緒に調べてみようよ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124042#originalText","id":"talk.lottery_pc_130124042","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我这次先放过你，要是再靠近的话我不会轻易饶过你的。","en":"Get out of my way. Get any closer and I won't be so merciful.","ja":"今は放っておいて近寄るなら容赦しないわよ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124043#originalText","id":"talk.lottery_pc_130124043","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"唔……！这种程度根本不算什么……！","en":"Tch...! How could this be?!","ja":"くっ……!この程度、なんてことない……!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124044#originalText","id":"talk.lottery_pc_130124044","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"雨缘……泷刳……","en":"Amayori... Takiguri...","ja":"雨縁……滝刳……"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124045#originalText","id":"talk.lottery_pc_130124045","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"就、就只有我穿学校的泳衣，太、太令人害羞了啦……","en":"I'm the only one here in my school swimsuit... T-This is...","ja":"あ、あたしだけスクール水着なんては、恥ずかしいよお……"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124046#originalText","id":"talk.lottery_pc_130124046","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"请、请你不要那样看我，太令人害臊了啦……","en":"P-Please, don't stare! You're embarrassing me!","ja":"そ、そんなに見ないでください恥ずかしいではありませんか……"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124047#originalText","id":"talk.lottery_pc_130124047","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"如果我也练习的话，是不是就会游泳了呀……","en":"I wonder if I just practiced... I'd be able to swim, too?","ja":"あたしも練習したら泳げるようになるかなぁ……"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124048#originalText","id":"talk.lottery_pc_130124048","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"好热呀～！想冲冲凉就把铠甲脱了！","en":"It is HOT! I want to go for a swim so I took off my armor!","ja":"暑いわね～!水浴びしたくて鎧脱いじゃった!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124049#originalText","id":"talk.lottery_pc_130124049","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"总觉得有点害羞呀。","en":"This is kinda embarassing...","ja":"なんだか恥ずかしいな"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124050#originalText","id":"talk.lottery_pc_130124050","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"身和心灵必须一同成长……作为集成骑士，才能保护人民。","en":"As an integrity knight, I must train my body and soul, so that I may protect our people.","ja":"心身ともに成長しなければ……整合騎士として、民を守れるように"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124051#originalText","id":"talk.lottery_pc_130124051","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"唔……右眼、好疼……","en":"Gah... My right eye... it hurts...","ja":"くっ……右目が、疼く……"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124052#originalText","id":"talk.lottery_pc_130124052","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"接下我不断钻研精进的剑技吧！！","en":"Just and try to parry my technique!","ja":"研ぎ澄まされたあたしの技受けてみなさい!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124053#originalText","id":"talk.lottery_pc_130124053","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"Trick or Treat。赌上糖果的比试……我这样理解对吗？","en":"Trick or treat... A competition for candy, perhaps?","ja":"トリック・オア・トリート菓子を賭けて勝負……という意味でしょうか?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124054#originalText","id":"talk.lottery_pc_130124054","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"使出全力吧！！","en":"I'll give it my all!","ja":"すべての力を出し切るっ!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124055#originalText","id":"talk.lottery_pc_130124055","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"因为，我有想要守护的事物。","en":"Because there's someone I want to protect.","ja":"あたしには、守りたいものがあるから"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124056#originalText","id":"talk.lottery_pc_130124056","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"应行之路上，贯彻始终。","en":"The only path is forward!","ja":"進むべき道を、ただ突き進むのみ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124057#originalText","id":"talk.lottery_pc_130124057","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"像这种也很适合我吧。","en":"This suits me, don't you think?","ja":"こういうのも似合うでしょ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124058#originalText","id":"talk.lottery_pc_130124058","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"只要穿上这个，总是不可思议地感到安心。","en":"Strangely enough, I feel comfortable when wearing this...","ja":"これを着ていると不思議と心が安らぎます"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124061#originalText","id":"talk.lottery_pc_130124061","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"用满满的活力上啰～！","en":"Ready, set, GO!","ja":"元気いっぱいで、いっくよー!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124063#originalText","id":"talk.lottery_pc_130124063","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"好甜～的味道呢！快、快打开看看！","en":"That smells lovely! Open up!","ja":"あま〜い香りがするわね!ほら、開けてみて!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124064#originalText","id":"talk.lottery_pc_130124064","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"是礼物哦。快收下吧。","en":"It's a present! So here you go!","ja":"贈り物ですよさぁ、受け取ってください"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124065#originalText","id":"talk.lottery_pc_130124065","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"在一起……原来是如此地幸福……","ja":"共にあること……それがこんなにも幸福とは……"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124066#originalText","id":"talk.lottery_pc_130124066","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"也不能再让你任意妄为下去了呀。","ja":"これ以上好き勝手させるわけにはいかないのよね"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124067#originalText","id":"talk.lottery_pc_130124067","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"呐呐，适合我吗～？","ja":"ねぇねぇ、似合う～?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124068#originalText","id":"talk.lottery_pc_130124068","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"这套服装感觉好轻，好像能轻飘飘地飞上天！","ja":"この衣装、なんだか軽くてふわふわ飛べちゃいそうだよ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124069#originalText","id":"talk.lottery_pc_130124069","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"我要变得更加更加强大才行。","ja":"もっともっと、強くならないと"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124070#originalText","id":"talk.lottery_pc_130124070","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"不是给我零食～让我恶作剧一下，也没关系吧？","ja":"お菓子じゃなくて、いたずらさせてくれてもいいのよ?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130124071#originalText","id":"talk.lottery_pc_130124071","speaker":{"en":"Eydis","ja":"イーディス"},"text":{"ja":"あなたに負けてられないからね"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130134003#originalText","id":"talk.lottery_pc_130134003","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"看来需要严厉点的惩罚。做好觉悟了吗？","en":"A little tough execution will be needed. You can handle it, right?","ja":"少々厳しい仕置きが必要だな覚悟はできてるね?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130134004#originalText","id":"talk.lottery_pc_130134004","speaker":{"cn":"Subtilizer","en":"Subtilizer","ja":"サトライザー"},"text":{"cn":"就让我来吸收你的灵魂吧。","en":"I'm going to absorb your soul!","ja":"魂を吸い取ってやろう"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130134005#originalText","id":"talk.lottery_pc_130134005","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"来放个大绝招吧！！","en":"Let's do it up big!","ja":"いっちょ大技やってやるか!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130134006#originalText","id":"talk.lottery_pc_130134006","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"快跟上吧！","en":"Don't be late!","ja":"遅れをとるなよ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130134007#originalText","id":"talk.lottery_pc_130134007","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"好，要上了！！","en":"Yahoooo! Here I come!","ja":"さーて、いきますかー!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130134008#originalText","id":"talk.lottery_pc_130134008","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"好，再增加点男子气概！","en":"Let's show them a real man's strength!","ja":"よーし、もっと男を上げてくぜぇ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144001#originalText","id":"talk.lottery_pc_130144001","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我会亳不吝啬地使出自己的技能喔！","en":"You won't be spared when I use my skill!","ja":"ボクのスキル出し惜しみはしないよ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144002#originalText","id":"talk.lottery_pc_130144002","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"请看着我吧。我要上了！！","en":"Look over me, okay? I'll take care of this!","ja":"見守っててくださいねあたし、やります!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144003#originalText","id":"talk.lottery_pc_130144003","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"没问题，因为我跟学长做了充分的修练呀！！","en":"No problem! All that training is about to pay off!","ja":"大丈夫、先輩とたっぷり修練したんだから!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144004#originalText","id":"talk.lottery_pc_130144004","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长！我和缇洁一起做了点心。你愿意⋯⋯收下它吗⋯⋯？","en":"Hey! I made snacks with Tiese. Would you like... some...?","ja":"先輩!ティーゼとお菓子作ったんです受け取って……いただけますか……?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144005#originalText","id":"talk.lottery_pc_130144005","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我现在去给花浇水。学长喜欢什么花呢？","en":"I came to water the flowers. What kind of flowers do you like, Kirito?","ja":"お花にお水をあげに行くんです先輩はどんな花がお好きですか?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144006#originalText","id":"talk.lottery_pc_130144006","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我也不会输喔，亚丝娜！","en":"I can't lose, Asuna!","ja":"ボクだって負けないよ、アスナ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144007#originalText","id":"talk.lottery_pc_130144007","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我很擅长游泳喔！学长，需要我教您吗？","en":"I'm pretty good at swimming! Should I teach you some pointers?","ja":"あたし、結構泳ぐの得意なんです!先輩、教えて差し上げましょうか?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144009#originalText","id":"talk.lottery_pc_130144009","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"Trick or Treat！","en":"Trick or treat!","ja":"トリック・オア・トリート!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144010#originalText","id":"talk.lottery_pc_130144010","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我要努力修练，变得更强。","en":"If you practice more, you'll get even stronger!","ja":"もっと修練して、強くなるんだ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144011#originalText","id":"talk.lottery_pc_130144011","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"只是能够在太阳伯伯的阳光下散步，我就已经觉得很兴奋了。","en":"Just taking a walk under the sun makes you feel so giddy, doesn't it?","ja":"おひさまの下を歩けるってそれだけでウキウキするんだ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144012#originalText","id":"talk.lottery_pc_130144012","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"刚好我在想你呢。难道说，你听见我的声音了？","en":"Good timing. I was just thinking about you. Could it be, you heard my voice?","ja":"ちょうどねあなたのことを考えてたのもしかして、私の声が聞こえた?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144013#originalText","id":"talk.lottery_pc_130144013","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"总觉得既温柔又一股沁香，令人感到安心……是因为你在身边吗？","en":"I feel so relaxed when you're around. You're so sweet to me, and smell so nice...","ja":"なんだか優しくて、いい匂いがして安心するんだ……キミがいるからかな?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144014#originalText","id":"talk.lottery_pc_130144014","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我去洗澡啰！","en":"Gonna go take a bath...","ja":"お風呂に行ってきます"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144015#originalText","id":"talk.lottery_pc_130144015","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长！不给糖就捣蛋！","en":"Kirito! Trick or treat!","ja":"先輩!トリック・オア・トリートです!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144016#originalText","id":"talk.lottery_pc_130144016","speaker":{"cn":"杏奈","en":"Anna","ja":"杏奈"},"text":{"cn":"再多一点再多一点！要炒热气氛啰！","en":"More, more! Things are only going to get more exciting!","ja":"もっともっと!ビビッと盛り上げていくよー!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144017#originalText","id":"talk.lottery_pc_130144017","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"为了最完美的舞台我会更加努力！","en":"I'll have to work harder for my shot in the spotlight!","ja":"最高のステージのためにもっと頑張ります!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144019#originalText","id":"talk.lottery_pc_130144019","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"总觉得兴奋了起来呀！","en":"I can hardly contain my excitement!","ja":"ボクなんだかワクワクしてきたよ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144020#originalText","id":"talk.lottery_pc_130144020","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"无论何处，我都会和剑一同前行。","en":"No matter where I go, my sword is by my side.","ja":"どこまでも、剣と共に歩んでいきます"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144021#originalText","id":"talk.lottery_pc_130144021","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"让你们见识见识我的大招！！","en":"I'll show you what I'm made of!","ja":"ボクの大技、見せちゃうよ!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130144022#originalText","id":"talk.lottery_pc_130144022","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"快点一起下水啦～！我最喜欢游泳了！","en":"Let's hurry up and jump in! I can't wait to go for a swim!","ja":"早く水に飛び込もうよ～!ボク泳ぐの大好き!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130164006#originalText","id":"talk.lottery_pc_130164006","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"好，那就走吧。","en":"Well, are we going then?","ja":"それじゃ、行くとするかね"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130214001#originalText","id":"talk.lottery_pc_130214001","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"助我一臂之力吧……伙伴！","en":"Help me...Comrade!","ja":"力を貸してくれ……相棒!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130214002#originalText","id":"talk.lottery_pc_130214002","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"接下这个世界里人们的意念吧……！","en":"Take this! The hopes of the people of this world!","ja":"受けてみろ……!この世界の人々の想いを……!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130214003#originalText","id":"talk.lottery_pc_130214003","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我才不是什么英雄呢，我只是……想守护大家罢了。","en":"I'm no hero. I just... I just want to protect people.","ja":"俺は英雄なんかじゃないさただ……守りたいんだ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130214004#originalText","id":"talk.lottery_pc_130214004","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"就由我来守护！","en":"I will protect you!","ja":"俺が守ってみせる!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130214005#originalText","id":"talk.lottery_pc_130214005","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不管是怎样的敌人我一定会攻略他们！","en":"Whoever the enemy is I'll be there to attack!","ja":"どんな敵だろうと必ず攻略してみせるぜ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130214006#originalText","id":"talk.lottery_pc_130214006","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"大家的心意……我绝对不会浪费掉的！！","en":"I won't let everyone down!","ja":"みんなの思い……絶対に無駄にはしない!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130214007#originalText","id":"talk.lottery_pc_130214007","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"所以，下个对手是谁啊？","en":"Who's next?","ja":"で、次はどいつが相手だ?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130214008#originalText","id":"talk.lottery_pc_130214008","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"啊抱歉，我有在听啦！所以……刚是在讲什么事啊？","en":"M-My bad, I was listening... What did you say again?","ja":"あぁ悪い、ちゃんと聞いてるって……で、なんの話だっけ?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130214009#originalText","id":"talk.lottery_pc_130214009","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我要让你见识……超越系统的意志力量！","en":"A will that can surpass the system...I'll show you!","ja":"システムを超える意思の力…… 見せてやる!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130214010#originalText","id":"talk.lottery_pc_130214010","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这世界上的LA奖励，全都是属于本大爷的！","en":"All of the LA bonuses in this world are MINE!","ja":"この世のLAボーナスはすべて俺様のものだ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130214011#originalText","id":"talk.lottery_pc_130214011","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"魔法奔流！","en":"Magical stream!","ja":"まじかるストリーム!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130224001#originalText","id":"talk.lottery_pc_130224001","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"怎么了？该不会，你刚好在找我吗？","en":"What's going on? You lookin' for me?","ja":"どうしたの? もしかしてわたしを探してたりして"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324001#originalText","id":"talk.lottery_pc_130324001","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我会保护你。所以，你也要保护我喔。","en":"I'll protect you. So, be sure to protect me, too.","ja":"君は私が守るだから君は、私を守ってね"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324002#originalText","id":"talk.lottery_pc_130324002","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"快点到地上。到桐人的身边去……","en":"I need to hurry and get above ground to where Kirito is...","ja":"早く、地上へキリトくんのところへ……"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324003#originalText","id":"talk.lottery_pc_130324003","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"天穿剑，就用这道光芒贯穿一切吧！！！","en":"It is the Heaven Piercing Sword! It will pierce through everything with it's light!","ja":"天穿剣よその光ですべてを穿て!!!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324004#originalText","id":"talk.lottery_pc_130324004","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"啊！","en":"Ahhhh!!","ja":"きゃあっ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324005#originalText","id":"talk.lottery_pc_130324005","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我不会死的。因为⋯⋯是我要守护你啊。","en":"I won't die. Remember?  Because I said I would protect you.","ja":"わたしは死なないよだってわたしは、君を守るほうだもん"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324007#originalText","id":"talk.lottery_pc_130324007","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"怎么了？","en":"How was it?","ja":"どうしたの?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324008#originalText","id":"talk.lottery_pc_130324008","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我帮大家回复！","en":"I'll heal everyone!","ja":"みんな回復するわね"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324009#originalText","id":"talk.lottery_pc_130324009","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"呵呵，我会好好疼爱你的。在那边跪下来吧。","en":"Hehe! I will love you accordingly. So kneel!","ja":"ふふ、可愛がってあげるから そこにひれ伏しなさい"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324010#originalText","id":"talk.lottery_pc_130324010","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"桐人守护过的世界……我也要守护下去！","en":"The world that Kirito protected... I'll show you that I can also protect it!","ja":"キリトくんが守った世界……私も守ってみせる!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324011#originalText","id":"talk.lottery_pc_130324011","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"接下来轮到我了，有纪！","en":"I'm up next, Yuuki!","ja":"次は私よ、ユウキ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324012#originalText","id":"talk.lottery_pc_130324012","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"爱是支配……爱是欲望！","en":"Love is control...love is desire!","ja":"愛は支配……愛は欲望!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324013#originalText","id":"talk.lottery_pc_130324013","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你……和你所守护的世界，我一定会传承下去。","en":"You too...You also protected this world.  And I will do the same!","ja":"君も……君が守ったこの世界も必ず私が繋ぐから"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324014#originalText","id":"talk.lottery_pc_130324014","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"为了能保持自我……我绝对不会输！","en":"To be myself... I will win, whatever the cost may be!","ja":"私が私でいるため……絶対に負けないわ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324015#originalText","id":"talk.lottery_pc_130324015","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我绝对不会输……！！","en":"I will not lose!","ja":"絶対に負けない……!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324017#originalText","id":"talk.lottery_pc_130324017","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"你要不要一起？呵呵，跟你开玩笑的啦⋯⋯","en":"And how about you joining along? Hehe. As if...","ja":"あなたも一緒にどう?ふふ、なんてね……冗談よ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324018#originalText","id":"talk.lottery_pc_130324018","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"哎呀，怎么了？哦～我猜你是肚子饿了吧？","en":"Something wrong? Ohhh, I know. You must be hungry.","ja":"あれ、どうしたの?あ、さてはお腹が空いたのね?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324019#originalText","id":"talk.lottery_pc_130324019","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"欸？已经饿了？真拿你没办法。","en":"What? Hungry already? Guess that's expected.","ja":"え? もうお腹すいた?まったく仕方ないなぁ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324020#originalText","id":"talk.lottery_pc_130324020","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你一定会来救我的对吧。桐人……","en":"Kirito will come save us. I just know it...","ja":"きっと助けに来てくれるよねキリトくん……"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324021#originalText","id":"talk.lottery_pc_130324021","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"一起上吧，伊斯卡恩……！","en":"Let's go together, Iskahn...!","ja":"一緒に来て。イスカーン……!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324022#originalText","id":"talk.lottery_pc_130324022","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"呵呵，喘口气吧！","en":"Hehe, shall we take a break?","ja":"ふふ、一息つきましょうか"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324023#originalText","id":"talk.lottery_pc_130324023","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"那个、桐人，我现在非常幸福哦……","en":"Kirito... I'm so happy...","ja":"あのね、キリトくんわたし、今すごく幸せだよ……"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324024#originalText","id":"talk.lottery_pc_130324024","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"太棒了……竟然这么浓稠甘甜！！","en":"Incredible...It's so rich and sweet!","ja":"凄いわ……なんて濃くて甘いの!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324025#originalText","id":"talk.lottery_pc_130324025","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"就再好好取悦我吧！","en":"Don't mind if I help myself to some fun!","ja":"もっと私を楽しませてちょうだい?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324026#originalText","id":"talk.lottery_pc_130324026","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"只要全变成散发光辉的石头的话，任何天命就都是同等的美丽了呢。","en":"All lifeforms would become equally beautiful if they could just become a preciou little gem.","ja":"輝く石の姿に変わってしまえばどんな天命も平等に美しいわね"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324027#originalText","id":"talk.lottery_pc_130324027","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天的任务应该没什么问题吧……晚点要向桐人确认一下才行。","en":"I wonder if today's quest will be alright... Gotta check with Kirito later.","ja":"今日のクエスト大丈夫かなぁ……後でキリトくんに確認しておかなきゃ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324028#originalText","id":"talk.lottery_pc_130324028","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"我会证明给你看的，保护我们的未来……","en":"I will protect our future...","ja":"守ってみせる私たちの未来を……"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324029#originalText","id":"talk.lottery_pc_130324029","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我不想输给这个世界。","en":"I won't submit to this world!","ja":"この世界には負けたくない"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324030#originalText","id":"talk.lottery_pc_130324030","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"来吧，我要上了！","en":"Let's get going!","ja":"さあ、行くわよ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324031#originalText","id":"talk.lottery_pc_130324031","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"呵呵，无论是怎样的敌人我一定会攻略他们的！","en":"Hehe, whoever the enemy is I'll be there to attack!","ja":"ふふ、どんな敵だって必ず攻略してみせるわ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324032#originalText","id":"talk.lottery_pc_130324032","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"是呀……静寂……喜欢哦。偶尔像这样的下雪夜晚似乎也不坏。","en":"Yes, I like the silence. Snowy nights are also splendid.","ja":"そうね……静寂は好きよ雪降る夜も、たまには悪くないわ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324033#originalText","id":"talk.lottery_pc_130324033","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"大家～！要上了喔～！！","en":"Let's go, everyone!","ja":"みんな～! いくよ～!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324034#originalText","id":"talk.lottery_pc_130324034","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天会有什么开心的事等着我呢？","en":"I wonder what fun things we'll do today!","ja":"今日はどんな楽しいことが待ってるかしら?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324035#originalText","id":"talk.lottery_pc_130324035","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"多依靠我一点吧？","en":"Trust in me more, promise?","ja":"もっと私を頼ってね?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324036#originalText","id":"talk.lottery_pc_130324036","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"嘻嘻，适合我吗？","ja":"ふふっ、似合うかな?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130324037#originalText","id":"talk.lottery_pc_130324037","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我已经下定决心不再停止不前了。","en":"I decided that I won't stop ever again.","ja":"もう立ち止まらないって決めたから"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130344001#originalText","id":"talk.lottery_pc_130344001","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长！我和罗妮耶一起做了点心。希望合你口味⋯⋯","en":"Hey! I made snacks with Ronie. I hope it suits your taste...","ja":"先輩!ロニエと一緒にお菓子を作ったんですお口に合うとよいのですが……"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130344002#originalText","id":"talk.lottery_pc_130344002","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"好～我来让这里变干净啰！","en":"Got it! I'll make the place spick and span!","ja":"よーし、綺麗にしちゃいますよ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130344003#originalText","id":"talk.lottery_pc_130344003","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"哟，桐人小子。你还好吗？","en":"Yo Kirito! How are you doing?","ja":"よっ、キー坊元気にしてるカ?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130344005#originalText","id":"talk.lottery_pc_130344005","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长！你等很久了吗……？","en":"Eugeo! Did I keep you waiting long...?","ja":"先輩!お待たせしちゃいましたか……?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130344006#originalText","id":"talk.lottery_pc_130344006","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"要不要就这样一起去游泳呢？","en":"Would you like to go for a swim like this?","ja":"このまま泳ぎに行きませんか?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130344007#originalText","id":"talk.lottery_pc_130344007","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"扮装后一起去茶会感觉会很开心！","en":"I can't wait to put on our costumes and do a tea party!","ja":"仮装してお茶会だなんてなんだか楽しそうですね!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130344008#originalText","id":"talk.lottery_pc_130344008","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"请问找我有事吗？","en":"Do you require my services?","ja":"わたくしにご用でしょうか"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130344009#originalText","id":"talk.lottery_pc_130344009","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我想变得更强⋯⋯","en":"I want to be strong...","ja":"強くなりたい……"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130344010#originalText","id":"talk.lottery_pc_130344010","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"要不要和我一起跳舞呢？","en":"Shall we dance?","ja":"あたしと躍りませんか?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130344011#originalText","id":"talk.lottery_pc_130344011","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"要不要去洗澡呢～","en":"A bath sounds good right now...","ja":"お風呂に行こうかな"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130344012#originalText","id":"talk.lottery_pc_130344012","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"我也是可以战斗的！","en":"Don't be fooled, I can fight too!","ja":"私だって、戦えるんです!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130454003#originalText","id":"talk.lottery_pc_130454003","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"我偶尔会跟赛尔一起去看星星。冬天的时候特别漂亮喔。","en":"Sometimes I go and look at the stars with Fizel. They're particularly beautiful in the winter!","ja":"ゼルとはたまに、星を観に行くんです特に冬はすごく綺麗なんですよ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130454004#originalText","id":"talk.lottery_pc_130454004","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"涅尔常常会很慌张，然后就跌倒。都是我扶他起来的。","en":"Linel is always tumbling around nervous. I'll go snap her out of it.","ja":"ネルったら慌ててよく転ぶのあたしが起こしてあげるんだ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130454006#originalText","id":"talk.lottery_pc_130454006","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"嗯⋯⋯总觉得有点困啊","en":"*Yawn... Kind of makes me want to sleep!","ja":"ふわぁ……なんだか眠たくなっちゃいました"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130454007#originalText","id":"talk.lottery_pc_130454007","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"不论是爸爸还是妈妈，都由我来守护！！","en":"I will protect you, Mama and Papa!","ja":"パパもママも、私が守ります!!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130454008#originalText","id":"talk.lottery_pc_130454008","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"我的名字叫卡迪娜尔，是维持这个世界秩序的人。","en":"My name is Cardinal. I am the one who corrects the order of this world.","ja":"わしの名はカーディナルこの世界の秩序を正す者"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130454009#originalText","id":"talk.lottery_pc_130454009","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我们会一起吃。你要不要一起？","en":"Everyone is going to eat. Would you like to join?","ja":"みんなで食べるんだ。君も一緒にどう?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130454010#originalText","id":"talk.lottery_pc_130454010","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"毕娜，要上啰。","en":"Let's go Pina!","ja":"ピナ、行くよっ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130454011#originalText","id":"talk.lottery_pc_130454011","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"父亲，请看那边！是金鸢狐的母子！","en":"Father, look! It's a golden flying fox with it's baby!","ja":"お父様、見てください!キントビギツネの親子です!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130454012#originalText","id":"talk.lottery_pc_130454012","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"嘿嘿……我尽了全力，做了这么多来喔。","en":"Hehe... I went a bit overboard and ended up making a lot.","ja":"えへへ……張り切っていっぱい作ってきちゃいました"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130454013#originalText","id":"talk.lottery_pc_130454013","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"不介意的话，也请尝尝我的巧克力！","en":"I have chocolates, too. Have some, if you'd like!","ja":"あたしのチョコレートもよかったら食べてください!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130454014#originalText","id":"talk.lottery_pc_130454014","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"Congratulation！达成使命了！","en":"Congratulations! Mission complete!","ja":"コングラチュレーション!ミッションクリアよ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130454015#originalText","id":"talk.lottery_pc_130454015","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"嘿嘿，因为我很想见爸爸，所以就飞过来了！","en":"Hehe, I missed you, so I flew here to see you!","ja":"えへへ、会いたくなって飛んできちゃいました!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130454016#originalText","id":"talk.lottery_pc_130454016","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"毕娜，请多指教啰！","en":"Pina, let's go!","ja":"ピナ、よろしくね!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130464005#originalText","id":"talk.lottery_pc_130464005","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"要是你能赢过我的话，骑士长这个位置就让给你吧。","en":"If you defeat me, you may have my position as Commander.","ja":"もしオレに勝てたら騎士長の座はお前さんのモンだ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130524001#originalText","id":"talk.lottery_pc_130524001","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"是不是稍微对我另眼相看了？","en":"Did you just reconsider me?","ja":"ちょっとはあたしのこと見直したかしら?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130524002#originalText","id":"talk.lottery_pc_130524002","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット "},"text":{"cn":"放马过来吧！！","en":"Come here!","ja":"かかってきなさーい!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130524003#originalText","id":"talk.lottery_pc_130524003","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"新年快乐！我们今年也要彼此多加油喔。","en":"Happy New Year! Let's both make it a good one.","ja":"あけましておめでとう今年も頑張りましょうねお互いに"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130524005#originalText","id":"talk.lottery_pc_130524005","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"尽管放马过来吧！","en":"Let's get going, everybody!","ja":"どっからでもかかってきなさい!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130624001#originalText","id":"talk.lottery_pc_130624001","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"强大并不是一种结果，只是距离目标的一个过程⋯⋯","en":"Strength isn't about the end result; it's about the journey...","ja":"強さは結果じゃなくそこを目指す過程にあるの……"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130624002#originalText","id":"talk.lottery_pc_130624002","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"怎么样？","en":"How is it?","ja":"どうかしら?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130624003#originalText","id":"talk.lottery_pc_130624003","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"就让我来教会你，被告知失败的子弹是什么味道吧。","en":"I'll teach you what defeat tastes like with this bullet!","ja":"教えてあげる敗北を告げる弾丸の味"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130624004#originalText","id":"talk.lottery_pc_130624004","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"助我一臂之力吧……黑卡蒂","en":"Lend me your strength, Hecate!","ja":"私に力を貸してね……ヘカート"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130624005#originalText","id":"talk.lottery_pc_130624005","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"好，要上啰！","en":"Let's get going!","ja":"さぁ、行くわよ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130624006#originalText","id":"talk.lottery_pc_130624006","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"一流的狙击手无论何时都能保持冷静哦。","en":"The best snipers are always calm no matter the situation.","ja":"一流の狙撃手はどんな時も冷静でいられるのよ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130724001#originalText","id":"talk.lottery_pc_130724001","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"不能连射？哼，那算什么问题。跟全自动比起来，我比较习惯单发的武器哟。","en":"No rapid-fire? Hmm, a single-shot weapon holds up much better than this low-tier fully automatic.","ja":"連射不可? ふん、上等じゃない全自動より、単発の武器のほうがしっくりくるってものだわ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130724002#originalText","id":"talk.lottery_pc_130724002","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"抱歉，我有点困。怎么了？","en":"Sorry, I doze off. What happended?","ja":"ごめん、ちょっとうとうとしてたどうしたの?"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130724003#originalText","id":"talk.lottery_pc_130724003","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"已经没事了。剩下的就交给我吧。","en":"It's alright. Just leave things to me.","ja":"もう大丈夫。あとは私に任せといて"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130724004#originalText","id":"talk.lottery_pc_130724004","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"我去大闹一场！","en":"I'll show you what I've got!","ja":"ひと暴れしてやるわ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130724005#originalText","id":"talk.lottery_pc_130724005","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"不会让你逃的！","en":"I won't let you get away!","ja":"逃がさないわよ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130724006#originalText","id":"talk.lottery_pc_130724006","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"如果是泳衣的话，很凉爽很棒呢！","en":"Bathing suits sure are breezy.","ja":"水着だと、涼しくていいわね"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130724007#originalText","id":"talk.lottery_pc_130724007","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"虽然我不是当偶像的料……","en":"Can't say idols are my thing...","ja":"アイドルなんて柄じゃないけど……"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130724008#originalText","id":"talk.lottery_pc_130724008","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"是令人感到凉爽又悦耳的声音呢，我很喜欢喔。","en":"What a breezy sound! I'll have to remember it.","ja":"涼しげでいい音ね気に入ったわ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_130764006#originalText","id":"talk.lottery_pc_130764006","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"集成骑士迪索尔巴德辛赛西斯‧赛门……要上了。","en":"Integrity Knight Deusolbert Synthesis Seven... At your service.","ja":"整合騎士デュソルバ—トシンセシス・セブン……参る"},"kind":"dialogue"},{"uid":"talk.lottery_pc_131214001#originalText","id":"talk.lottery_pc_131214001","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"我要用这拳头，粉碎一切！！","en":"With this fist, I'll crush everything!","ja":"この拳で、全部突き破ってやらぁっ!!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_131214002#originalText","id":"talk.lottery_pc_131214002","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"喔，交给我吧！谢达！","en":"I'll leave it to you, Sheyta!","ja":"おう、任せろ! シェータ!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_131214003#originalText","id":"talk.lottery_pc_131214003","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"我会把这变成不输人界的好国家给你看的！","en":"We'll build a country that's even better than the Human Empire!","ja":"人界にも負けねぇぐらいいい国にしてやるぜ"},"kind":"dialogue"},{"uid":"talk.lottery_pc_131214004#originalText","id":"talk.lottery_pc_131214004","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这个放在肩膀上的狼很帅气吧！","en":"Hey this outfit doesn't look too shabby on me!","ja":"この肩についてる狼格好いいよな!"},"kind":"dialogue"},{"uid":"talk.lottery_pc_alice_1#originalText","id":"talk.lottery_pc_alice_1","speaker":{},"text":{"cn":"有时候，我会梦到一个风景。梦到被绿色草木包围着的，平静安稳的村庄……","en":"I sometimes see it in my dreams.  A scene of a village surrounded my trees..."},"kind":"narration"},{"uid":"talk.lottery_pc_alice_2#originalText","id":"talk.lottery_pc_alice_2","speaker":{},"text":{"cn":"你下次再敢说蠢话，就事先做好头跟身体分开的觉悟吧","en":"The next time you call me dumb,  I hope you’re prepared to lose your head."},"kind":"narration"},{"uid":"talk.lottery_pc_alice_3#originalText","id":"talk.lottery_pc_alice_3","speaker":{},"text":{"cn":"老实说，我不太喜欢元老长阁下……而且我认为那华丽过头的外表，也脱离了教会的本质","en":"To be blunt, I'm not fond of the previous elder.  He was concerned more with appearances  rather than the teachings of the Church."},"kind":"narration"},{"uid":"talk.lottery_pc_asuna_1#originalText","id":"talk.lottery_pc_asuna_1","speaker":{},"text":{"cn":"真是的……我一直一直很担心你啊！","en":"Jeez... I was so worried about you!"},"kind":"narration"},{"uid":"talk.lottery_pc_asuna_2#originalText","id":"talk.lottery_pc_asuna_2","speaker":{},"text":{"cn":"那把剑……很适合你耶","en":"That sword...really suits you."},"kind":"narration"},{"uid":"talk.lottery_pc_asuna_3#originalText","id":"talk.lottery_pc_asuna_3","speaker":{},"text":{"cn":"这个世界好漂亮啊……如果没有战争的话，真想悠闲地在这里旅行","en":"What a wonderful world...  It'd make a perfect vacation  spot if it weren’t for the war."},"kind":"narration"},{"uid":"talk.lottery_pc_eugeo_1#originalText","id":"talk.lottery_pc_eugeo_1","speaker":{},"text":{"cn":"不知不觉，像这样两个人在一起已经变得理所当然了","en":"I don't when it happened, but it feels natural that we're together like this."},"kind":"narration"},{"uid":"talk.lottery_pc_eugeo_2#originalText","id":"talk.lottery_pc_eugeo_2","speaker":{},"text":{"cn":"真是的，你老是在勉强自己。你也体谅一下每次都得阻止你的我吧","en":"Quit going overboard all the time.  Learn some restraint, will you? "},"kind":"narration"},{"uid":"talk.lottery_pc_eugeo_3#originalText","id":"talk.lottery_pc_eugeo_3","speaker":{},"text":{"cn":"就由我来教你神圣术吧。想逃也是没用的喔","en":"I'll teach you Sacred Arts.  There’s no point in trying to escape."},"kind":"narration"},{"uid":"talk.lottery_pc_kirito_1#originalText","id":"talk.lottery_pc_kirito_1","speaker":{},"text":{"cn":"嗨，我正想见你呢","en":"Great! Just the guy I wanted to see!"},"kind":"narration"},{"uid":"talk.lottery_pc_kirito_2#originalText","id":"talk.lottery_pc_kirito_2","speaker":{},"text":{"cn":"来打个赌吧输的人请喝饮料怎么样？","en":"Let’s bet on it! The loser buys the winner a drink!"},"kind":"narration"},{"uid":"talk.lottery_pc_kirito_3#originalText","id":"talk.lottery_pc_kirito_3","speaker":{},"text":{"cn":"啊，你来的正好！要不要跟我一起去练习啊？","en":"Nice timing! How about going a round with me?"},"kind":"narration"},{"uid":"talk.lottery_pc_leafa_1#originalText","id":"talk.lottery_pc_leafa_1","speaker":{},"text":{"cn":"我不是很想看到你躺在床上的样子。能像这样伴在彼此身边才好","en":"I don't want to watch you asleep in some bed.  I want to stay together like this."},"kind":"narration"},{"uid":"talk.lottery_pc_leafa_2#originalText","id":"talk.lottery_pc_leafa_2","speaker":{},"text":{"cn":"我总觉得这个世界和游戏不一样，是个很像现实的奇幻作品","en":"This world... It's not a game,  but it feels like a fantasy world similar to reality."},"kind":"narration"},{"uid":"talk.lottery_pc_leafa_3#originalText","id":"talk.lottery_pc_leafa_3","speaker":{},"text":{"cn":"你在现实世界也这么认真练剑道的话，一定会比我还要强的说！","en":"You were so much stronger than me  when we did kendo in the real world!"},"kind":"narration"},{"uid":"talk.lottery_pc_ronye_1#originalText","id":"talk.lottery_pc_ronye_1","speaker":{},"text":{"cn":"今日的打扫工作已经顺利完成！","en":"Today's cleaning is finished!"},"kind":"narration"},{"uid":"talk.lottery_pc_ronye_2#originalText","id":"talk.lottery_pc_ronye_2","speaker":{},"text":{"cn":"你是在哪里学会《艾恩葛朗特流》的呢？","en":"Where did you learn your Aincrad-style?"},"kind":"narration"},{"uid":"talk.lottery_pc_ronye_3#originalText","id":"talk.lottery_pc_ronye_3","speaker":{},"text":{"cn":"之前拿到的跳鹿亭蜂蜜派真的很好吃！","en":"Thank you for the Jumping Deer honey pies the other day!  They were delicious!"},"kind":"narration"},{"uid":"talk.lottery_pc_tiese_1#originalText","id":"talk.lottery_pc_tiese_1","speaker":{},"text":{"cn":"报告！已经完成今日的打扫工作！","en":"Reporting in!  Today's cleaning is finished!"},"kind":"narration"},{"uid":"talk.lottery_pc_tiese_2#originalText","id":"talk.lottery_pc_tiese_2","speaker":{},"text":{"cn":"我认为身为贵族本身就伴随着责任。守护市民的责任……","en":"As Elites, we have a responsibility to withhold.  That is, to protect the citizens..."},"kind":"narration"},{"uid":"talk.lottery_pc_tiese_3#originalText","id":"talk.lottery_pc_tiese_3","speaker":{},"text":{"cn":"你选我做为随侍这件事，真的令我感到非常光荣……","en":"It's an honor to be your valet."},"kind":"narration"},{"uid":"talk.lottery_pc_yuuki_1#originalText","id":"talk.lottery_pc_yuuki_1","speaker":{},"text":{"cn":"树木、地面、天空……全部都好像真的一样嘿嘿，有种好不可思议的感觉","en":"It's no different from the real thing.  The trees, ground, even the sky...  It's kinda crazy when you think about it."},"kind":"narration"},{"uid":"talk.lottery_pc_yuuki_2#originalText","id":"talk.lottery_pc_yuuki_2","speaker":{},"text":{"cn":"在这个世界可以骑在龙的背上对不对！？我好想骑看看喔","en":"You can ride dragons in this world, right?!  I wanna give it a try!"},"kind":"narration"},{"uid":"talk.lottery_pc_yuuki_3#originalText","id":"talk.lottery_pc_yuuki_3","speaker":{},"text":{"cn":"我也想更加磨炼自己的技术！","en":"I want to improve my skills, too!"},"kind":"narration"}]};
